import 'dart:convert';
import 'dart:io';

import 'package:smollm2/smollm2.dart';

/// SmolLM2 Vocabulary encoded as: JSON → UTF-8 → GZIP → Base64.
///
/// The original vocabulary is a JSON list of strings, compressed using GZIP
/// and then encoded as Base64 for compact storage and transport.
///
/// To generate this value:
///
/// ```dart
/// final encoded = base64.encode(
///   gzip.encode(
///     utf8.encode(json.encode(t.vocab)),
///   ),
/// );
/// print(encoded);
/// ```
///
/// Decoding order is the reverse:
/// Base64 → GZIP → UTF-8 → JSON.
///
/// Example:
/// ```dart
/// final bytes = base64.decode(encoded);
/// final jsonStr = utf8.decode(gzip.decode(bytes));
/// final vocab = json.decode(jsonStr);
/// ```
final smolLM2TokenizerMergesBase64 = '''

''';

/// SmolLM2 merge table encoded as:
/// JSON → UTF-8 → GZIP → Base64.
///
/// The merge list is flattened before encoding:
/// each pair (a, b) becomes a sequential list: [a, b, a, b, ...]
///
/// Encoding process:
///
/// ```dart
/// final flat = t.merges.expand((e) => [e.$1, e.$2]).toList();
///
/// final encoded = base64.encode(
///   gzip.encode(
///     utf8.encode(json.encode(flat)),
///   ),
/// );
///
/// print(encoded);
/// ```
///
/// Decoding order is reversed:
/// Base64 → GZIP → UTF-8 → JSON → reconstruct pairs.
///
/// To rebuild merges:
/// ```dart
/// final list = json.decode(jsonStr) as List;
/// final merges = [
///   for (int i = 0; i < list.length; i += 2)
///     (list[i], list[i + 1]),
/// ];
/// ```
final smolLM2MergesBase64 = '''

''';

final smolLM2TokenizerVocabulary = _decodeVocabulary(
  smolLM2TokenizerMergesBase64,
);

List<String> _decodeVocabulary(String b64) {
  var comp = base64.decode(b64.trim());
  var bs = GZipCodec().decode(comp);
  var j = utf8.decode(bs);
  var l = json.decode(j) as List;
  var v = l.map((e) => '$e').toList();
  return v;
}

final smolLM2TokenizerMerges = _decodeMerges(smolLM2TokenizerMergesBase64);

List<(String, String)> _decodeMerges(String b64) {
  final compressedBytes = base64.decode(b64.trim());

  final decompressedBytes = gzip.decode(compressedBytes);

  final jsonStr = utf8.decode(decompressedBytes);

  final list = json.decode(jsonStr) as List;

  final merges = <(String, String)>[];

  for (int i = 0; i < list.length; i += 2) {
    var a = list[i].toString();
    var b = list[i + 1].toString();
    merges.add((a, b));
  }

  return merges;
}

